// Actual historical demonstration inputs, packaged independently of authoring prompts.
let iclPackagesPromise;
let iclRequest=0;
const iclView={packages:[],task:'install_gear',frame:0,tab:'frames'};
const iclEscape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iclTaskName=task=>task.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const iclNumber=value=>JSON.stringify(value,(_,v)=>typeof v==='number'?Number(v.toFixed(5)):v)??'—';
function iclFrames(pkg){return pkg.inputs.flatMap((input,index)=>input.type==='localImage'?[{...input,caption:pkg.inputs[index-1]?.text||'Historical demonstration keyframe',promptBlock:index,imageBlock:index+1}]:[]);}
function iclText(text){return text.split('\n').filter(line=>line.trim()).map(line=>{try{const value=JSON.parse(line);if(value&&typeof value==='object')return `<pre class="icl-json">${iclEscape(JSON.stringify(value,null,2))}</pre>`;}catch{}return `<p>${iclEscape(line)}</p>`;}).join('');}
function iclRecords(pkg){return pkg.inputs.filter(x=>x.type==='text').flatMap(x=>x.text.split('\n').flatMap(line=>{try{const value=JSON.parse(line);return typeof value==='object'&&value!==null?[value]:[];}catch{return [];}}));}
async function openICLPackage(task='install_gear'){
 const request=++iclRequest,dialog=document.querySelector('#appendix-dialog'),body=document.querySelector('#appendix-body');
 dialog.dataset.content='icl';dialog.classList.add('icl-dialog');
 body.innerHTML='<h2 id="appendix-title">Inside a single-shot ICL package</h2><p role="status">Loading the recorded demonstration…</p>';
 if(!dialog.open)dialog.showModal();dialog.scrollTop=0;
 try{
  if(!iclPackagesPromise)iclPackagesPromise=fetch('data/icl-packages.json').then(r=>{if(!r.ok)throw Error('ICL data');return r.json();}).catch(error=>{iclPackagesPromise=null;throw error;});
  const packages=await iclPackagesPromise;
  if(request!==iclRequest||dialog.dataset.content!=='icl'||!dialog.open)return;
  iclView.packages=packages;iclView.task=packages.some(p=>p.task===task)?task:packages[0].task;iclView.frame=0;iclView.tab='frames';renderICLPackage();
 }catch{if(request===iclRequest&&dialog.dataset.content==='icl')body.innerHTML='<h2 id="appendix-title">Demonstration data unavailable</h2><p>Please reload and open the package again.</p>';}
}
function renderICLPackage(){
 const pkg=iclView.packages.find(p=>p.task===iclView.task),frames=iclFrames(pkg),body=document.querySelector('#appendix-body');
 body.innerHTML=`<h2 id="appendix-title">Inside a single-shot ICL package</h2><p class="icl-intro">The actual historical reference supplied to GPT-6-Astra: <strong>annotated images, operation descriptions, and recorded state/action examples</strong>. A separate GPT-6-Astra instance with <code>high</code> reasoning effort reviews one training-set video per task, autonomously selects keyframes, and writes the accompanying prompts. Browse a task or inspect its complete input sequence.</p><div class="icl-toolbar"><label for="icl-task">Demonstration task<select id="icl-task">${iclView.packages.map(p=>`<option value="${iclEscape(p.task)}" ${p.task===pkg.task?'selected':''}>${iclTaskName(p.task)}</option>`).join('')}</select></label><span>${frames.length} images · one historical trajectory</span></div><div class="icl-tabs" role="tablist" aria-label="Demonstration presentation"><button id="icl-tab-frames" role="tab" aria-controls="icl-panel" aria-selected="${iclView.tab==='frames'}" tabindex="${iclView.tab==='frames'?0:-1}" data-icl-view="frames">Keyframes & recorded data</button><button id="icl-tab-inputs" role="tab" aria-controls="icl-panel" aria-selected="${iclView.tab==='inputs'}" tabindex="${iclView.tab==='inputs'?0:-1}" data-icl-view="inputs">Complete ICL input</button></div><div id="icl-panel" role="tabpanel" aria-labelledby="icl-tab-${iclView.tab}"></div><p class="icl-source-note">Historical reference images may include a top view; live execution uses overview and wrist cameras. Source coordinates are examples, not replayed commands. Historical demonstrations have no official success labels.</p>`;
 renderICLPanel();
}
function renderICLPanel(){
 const pkg=iclView.packages.find(p=>p.task===iclView.task),frames=iclFrames(pkg),panel=document.querySelector('#icl-panel');
 if(iclView.tab==='inputs'){
  panel.innerHTML=`<div class="icl-input-heading"><p>All ${pkg.inputs.length} input blocks, in their supplied order. Only image file paths have been relocated for this website.</p><button class="appendix-link" data-icl-download>Download this ICL package JSON ↓</button></div><div class="icl-input-sequence">${pkg.inputs.map((input,i)=>`<section class="icl-input-block"><span class="icl-block-label">${String(i+1).padStart(2,'0')} / ${input.type==='text'?'TEXT':'IMAGE'}</span>${input.type==='text'?iclText(input.text):`<img src="${iclEscape(input.path)}" loading="lazy" alt="${iclEscape(pkg.inputs[i-1]?.text||'Historical keyframe')}"/>`}</section>`).join('')}</div>`;
  return;
 }
 const frame=frames[iclView.frame],frameNumber=Number(frame.caption.match(/frame\s+(\d+)/i)?.[1]),records=iclRecords(pkg),record=records.find(r=>Number(r.frame)===frameNumber),intro=pkg.inputs.find(p=>p.type==='text')?.text||'';
 panel.innerHTML=`<div class="icl-album" tabindex="0" role="group" aria-label="Keyframe album; use left and right arrow keys"><button class="icl-album-arrow" data-icl-step="-1" ${iclView.frame===0?'disabled':''} aria-label="Previous keyframe">‹</button><div class="icl-frame-pair"><figure class="icl-frame-view"><div class="icl-image-stage"><img src="${iclEscape(frame.path)}" alt="${iclEscape(frame.caption)}" aria-describedby="icl-frame-prompt"/></div></figure><aside class="icl-frame-prompt" aria-label="Prompt supplied with the selected keyframe"><span class="icl-prompt-label">FRAME PROMPT · ORIGINAL INPUT</span><h3>What accompanies this image</h3><p class="icl-prompt-block">Text input ${frame.promptBlock} → image input ${frame.imageBlock}</p><blockquote id="icl-frame-prompt" aria-live="polite">${iclEscape(frame.caption)}</blockquote><p class="icl-prompt-note">Exact text supplied immediately before this image in the historical ICL package.</p></aside></div><button class="icl-album-arrow" data-icl-step="1" ${iclView.frame===frames.length-1?'disabled':''} aria-label="Next keyframe">›</button></div><p id="icl-frame-caption" class="icl-album-caption">Historical keyframe ${iclView.frame+1} of ${frames.length} · image input ${frame.imageBlock}</p><div class="icl-frame-controls"><label>Keyframe <output>${iclView.frame+1} / ${frames.length}</output><input aria-label="Select demonstration keyframe" type="range" min="0" max="${frames.length-1}" value="${iclView.frame}" id="icl-frame-range"/></label></div><div class="icl-filmstrip" aria-label="All demonstration keyframes">${frames.map((f,i)=>`<button data-icl-frame="${i}" aria-label="Keyframe ${i+1}" aria-pressed="${i===iclView.frame}"><img src="${iclEscape(f.path)}" loading="lazy" alt=""/><span>${i+1}</span></button>`).join('')}</div><div class="icl-record-section"><h3>Recorded state & action targets</h3><p>Aligned by source frame. Measured state and exported targets are separate; values below are rounded to five decimal places. Complete input retains original precision.</p>${record?iclRecordTable(record):'<p class="fineprint">This image has no matching numeric excerpt in the supplied package.</p>'}</div><details class="icl-context"><summary>Shared task prompt · applies to every keyframe</summary><div>${iclText(intro.split('\n').filter(line=>!line.trim().startsWith('{')).join('\n'))}</div></details>`;
}
function iclRecordTable(record){
 let measured=record.measured,action=record.exported_action;
 if(!measured&&record.measured_left_xyz_wxyz){measured={left_xyz_wxyz:record.measured_left_xyz_wxyz,left_total_gap_m:record.measured_left_total_gap_m};action={left_xyz_wxyz:record.exported_action_left_xyz_wxyz,left_total_gap_m:record.command_left_total_gap_m};}
 if(measured&&action){const fields=[...new Set([...Object.keys(measured),...Object.keys(action)])];return `<div class="icl-data-scroll"><table class="icl-data-table"><thead><tr><th>Source field</th><th>Measured state</th><th>Exported action target</th></tr></thead><tbody>${fields.map(field=>`<tr><th>${iclEscape(field)}</th><td>${iclEscape(iclNumber(measured[field]))}</td><td>${iclEscape(iclNumber(action[field]))}</td></tr>`).join('')}</tbody></table></div><details class="icl-raw"><summary>Original numeric record · frame ${iclEscape(record.frame)}</summary><pre class="icl-json">${iclEscape(JSON.stringify(record,null,2))}</pre></details>`;}
 return `<div class="icl-data-scroll"><table class="icl-data-table"><thead><tr><th>Source field</th><th>Recorded value</th></tr></thead><tbody>${Object.entries(record).map(([field,value])=>`<tr><th>${iclEscape(field)}</th><td>${iclEscape(iclNumber(value))}</td></tr>`).join('')}</tbody></table></div>`;
}
function selectICLFrame(index){const strip=document.querySelector('.icl-filmstrip'),offset=strip?.scrollLeft||0;iclView.frame=index;renderICLPanel();document.querySelector('.icl-filmstrip').scrollLeft=offset;}
document.addEventListener('change',e=>{if(e.target.id==='icl-task'){iclView.task=e.target.value;iclView.frame=0;renderICLPanel();const pkg=iclView.packages.find(p=>p.task===iclView.task);document.querySelector('.icl-toolbar>span').textContent=`${iclFrames(pkg).length} images · one historical trajectory`;}if(e.target.id==='icl-frame-range'){selectICLFrame(Number(e.target.value));document.querySelector('#icl-frame-range').focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(e.target.id==='icl-frame-range')e.target.parentElement.querySelector('output').textContent=`${Number(e.target.value)+1} / ${Number(e.target.max)+1}`;});
document.addEventListener('click',e=>{
 let button=e.target.closest('[data-icl-package]');if(button){openICLPackage(button.dataset.iclPackage||'install_gear');return;}
 button=e.target.closest('[data-icl-view]');if(button){iclView.tab=button.dataset.iclView;renderICLPackage();document.querySelector('#icl-tab-'+iclView.tab).focus({preventScroll:true});return;}
 button=e.target.closest('[data-icl-frame]');if(button){selectICLFrame(Number(button.dataset.iclFrame));document.querySelector(`[data-icl-frame="${iclView.frame}"]`).focus({preventScroll:true});return;}
 button=e.target.closest('[data-icl-step]');if(button){const step=button.dataset.iclStep;selectICLFrame(iclView.frame+Number(step));const next=document.querySelector(`[data-icl-step="${step}"]`);(next.disabled?document.querySelector('.icl-album'):next).focus({preventScroll:true});return;}
 if(e.target.closest('[data-icl-download]')){const pkg=iclView.packages.find(p=>p.task===iclView.task),url=URL.createObjectURL(new Blob([JSON.stringify(pkg,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=pkg.task+'-icl.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-icl-view]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();iclView.tab=e.key==='Home'?'frames':e.key==='End'?'inputs':iclView.tab==='frames'?'inputs':'frames';renderICLPackage();document.querySelector('#icl-tab-'+iclView.tab).focus({preventScroll:true});});

function pairedICLContent(){
 const groups=ablations.groups.filter(g=>g.experiment==='frame_gear_fresh'),pairs=ablations.pairs.filter(p=>p.experiment==='frame_gear_fresh'),historical=ablations.pairs.filter(p=>p.experiment!=='frame_gear_fresh');
 const rows=ps=>ps.map(p=>`<tr><th>${title(p.task)} / ${p.seed}</th><td>${p.zero_shot_sr}</td><td>${p.zero_shot_score.toFixed(4)}</td><td>${p.icl_sr}</td><td>${p.icl_score.toFixed(4)}</td><td>${p.delta_score>0?'+':''}${p.delta_score.toFixed(4)}</td></tr>`).join('');
 const table=ps=>`<div class="table-scroll"><table class="paired-detail-table"><thead><tr><th rowspan="2">Task / seed</th><th colspan="2">Zero-shot</th><th colspan="2">Single-shot ICL</th><th rowspan="2">Δ Score</th></tr><tr><th>SR</th><th>Score</th><th>SR</th><th>Score</th></tr></thead><tbody>${rows(ps)}</tbody></table></div>`;
 return ['Paired ICL results: gains and regressions',`<p><strong>Eight matched pairs, sixteen fresh episodes</strong>, separate from the main 510-episode cohort. Both conditions share execution guidance and resource settings; only the annotated demonstration is switched on or off.</p><div class="icl-pair-findings">${groups.map(g=>`<section><h3>${title(g.task)}</h3><p><strong>${g.zero_shot_successes}/${g.pairs} → ${g.icl_successes}/${g.pairs}</strong> complete successes</p><p>Mean Score ${g.zero_shot_score.toFixed(4)} → ${g.icl_score.toFixed(4)}</p><p>${g.score_better} pairs improve · ${g.score_worse} worsen · ${g.score_tied} tie</p><button class="appendix-link" data-icl-package="${g.task}">Inspect this task’s demonstration ↗</button></section>`).join('')}</div><h3>All eight pairs</h3>${table(pairs)}<p><strong>Terminal success includes any holding phase.</strong> Frame ICL seed 003 receives success after 1,032 policy steps and 520 holding steps. Gear ICL seed 001 succeeds after 541 policy steps without holding.</p><p class="fineprint">The two tasks were selected after earlier pilots; seed 000 repeats a scene. This targeted comparison does not estimate average ICL gains over all benchmark tasks or exclusively unseen scenes.</p><details class="icl-context"><summary>Separate historical comparison: dishwasher</summary><p>Five new zero-shot runs are compared with historical ICL episodes. Inference channels and dates differ. Neither condition succeeds; this is not part of the eight fresh pairs above.</p>${table(historical)}</details>`];
}

document.addEventListener('keydown',e=>{if(!e.target.closest('.icl-album')||!['ArrowLeft','ArrowRight'].includes(e.key)||e.target.matches('input,select,textarea'))return;e.preventDefault();const pkg=iclView.packages.find(p=>p.task===iclView.task),next=Math.max(0,Math.min(iclFrames(pkg).length-1,iclView.frame+(e.key==='ArrowRight'?1:-1)));if(next!==iclView.frame)selectICLFrame(next);document.querySelector('.icl-album').focus({preventScroll:true});});
